def transform(grid):
    g = np.array(grid)
    Hh, Ww = g.shape
    filler = g[Hh - 1, Ww - 1]
    nonf = g != filler
    rows = [y for y in range(Hh) if nonf[y].any()]
    cols = [x for x in range(Ww) if nonf[:, x].any()]
    H = max(rows) + 1
    W = max(cols) + 1
    block = g[:H, :W]

    def period(axis):
        n = block.shape[axis]
        for p in range(1, n + 1):
            if axis == 0:
                if np.array_equal(block[p:], block[:n - p]):
                    return p
            else:
                if np.array_equal(block[:, p:], block[:, :n - p]):
                    return p
        return n

    py, px = period(0), period(1)
    tile = block[:py, :px]

    ext = np.zeros_like(g)
    for y in range(Hh):
        for x in range(Ww):
            ext[y, x] = tile[y % py, x % px]
    emit(ext, "Extend the repeating pattern from the top-left block over the whole grid, replacing the filler colour.")

    out = np.zeros_like(g)
    for y in range(Hh):
        for x in range(Ww):
            out[y, x] = tile[y % py, (x + 1) % px]
    emit(out, "Shift the whole tiling one column to the left (each cell takes the pattern value from its right neighbour).")
    return out
